'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var ones = require( '@stdlib/ndarray/ones' );
var zeros = require( '@stdlib/ndarray/zeros' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var pow = require( '@stdlib/math/base/special/pow' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var resolveTriangle = require( '@stdlib/blas/base/matrix-triangle-resolve-enum' );
var resolveTranspose = require( '@stdlib/blas/base/transpose-operation-resolve-enum' );
var resolveDiagonal = require( '@stdlib/blas/base/diagonal-type-resolve-enum' );
var striu = require( '@stdlib/blas/ext/base/ndarray/striu' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var strsv = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'float32'
};
var eopts = {
	'dtype': 'int32'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var trans;
	var diag;
	var uplo;
	var M;
	var A;
	var k;
	var x;

	M = ones( [ N, N ], options );
	A = zeros( [ N, N ], options );
	k = scalar2ndarray( 0, {
		'dtype': 'generic'
	});
	striu( [ M, A, k ] );

	x = zeros( [ N ], options );

	uplo = scalar2ndarray( resolveTriangle( 'upper' ), eopts );
	trans = scalar2ndarray( resolveTranspose( 'no-transpose' ), eopts );
	diag = scalar2ndarray( resolveDiagonal( 'unit' ), eopts );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var z;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = strsv( [ A, x, uplo, trans, diag ] );
			if ( typeof z !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( isnanf( z.get( i%N ) ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var N;
	var f;
	var i;

	min = 1; // 10^min
	max = 3; // 10^max

	for ( i = min; i <= max; i++ ) {
		N = pow( 10, i );
		f = createBenchmark( N );
		bench( format( '%s:size=%d', pkg, N*N ), f );
	}
}

main();
